<?php $items=$reservations??[];$reservable=$areas??[];$canReserve=!empty($residentContext['can_reserve']);?>
<section class="resident-page-title"><span>Espacios comunes</span><h1>Áreas y reservas</h1><p>Información real de las áreas creadas en la instalación.</p></section>
<div class="resident-area-list"><?php foreach($reservable as $area):?><article><span class="area-photo-placeholder"><i class="<?=e($area['icon'])?>"></i></span><div><strong><?=e($area['name'])?></strong><small><?=e($area['location'])?><?=!empty($area['capacity'])?' · Cap. '.e($area['capacity']):''?></small><span><?=e($area['schedule'])?></span></div><i class="bi bi-chevron-right"></i></article><?php endforeach;?><?php if(!$reservable):?><div class="resident-empty">La administración todavía no ha marcado áreas como reservables.</div><?php endif;?></div>
<?php if($reservable&&$canReserve):?><button class="resident-primary-button resident-floating-action" data-bs-toggle="modal" data-bs-target="#reservationModal"><i class="bi bi-calendar-plus"></i> Solicitar reserva</button><?php endif;?>
<section class="resident-section"><div class="section-heading"><h2>Mis solicitudes</h2></div><?php foreach($items as $r):?><article class="mobile-list-card"><span class="date-tile"><strong><?=e(date('d',strtotime((string)$r['starts_at'])))?></strong><small><?=e(strtoupper(date('M',strtotime((string)$r['starts_at']))))?></small></span><div><strong><?=e($r['area'])?></strong><span><?=e(date('H:i',strtotime((string)$r['starts_at'])))?>–<?=e(date('H:i',strtotime((string)$r['ends_at'])))?> · <?=e($r['purpose'])?></span><small><?=e($r['unit'])?></small></div><span class="status-pill status-<?=e(status_badge((string)$r['status']))?>"><?=e(status_label((string)$r['status']))?></span></article><?php endforeach;?><?php if(!$items):?><div class="resident-empty">No tienes solicitudes de reserva.</div><?php endif;?></section>
<?php if($reservable&&$canReserve):?><div class="modal fade" id="reservationModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content resident-modal" method="post" action="<?=url('create-reservation')?>"><?=csrf_field()?><input type="hidden" name="return_route" value="resident-reservations"><div class="modal-header"><div><h5 class="modal-title">Solicitar reserva</h5><small>La disponibilidad se valida contra la base real</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body resident-form"><label>Área<select name="area_id" required><?php foreach($reservable as $area):?><option value="<?=$area['id']?>"><?=e($area['name'])?> · <?=e($area['location'])?></option><?php endforeach;?></select></label><label>Finalidad<input name="purpose" required placeholder="Reunión, celebración, trabajo..."></label><label>Fecha<input type="date" name="date" min="<?=date('Y-m-d')?>" required></label><div class="form-row"><label>Desde<input type="time" name="start" required></label><label>Hasta<input type="time" name="end" required></label></div><label>Asistentes<input type="number" name="attendees" min="1" value="1"></label></div><div class="modal-footer"><button class="resident-secondary-button" type="button" data-bs-dismiss="modal">Cancelar</button><button class="resident-primary-button">Enviar solicitud</button></div></form></div></div><?php endif;?>
